use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let str_input = input.as_str().unwrap();
    let mut parts = str_input.split('.');
    let mut amount = 0;
    let mut sign = 1;
    let mut has_dot = false;

    if let Some(first_part) = parts.next() {
        let amount_str = first_part.trim();
        if let Some(amount_str) = amount_str.trim() {
            let amount = amount_str.parse::<i64>().unwrap();
            if amount < -1000000 || amount > 1000000 {
                return Value::Null;
            }
            amount *= sign;
            has_dot = true;
        }
    }

    if let Some(second_part) = parts.next() {
        let amount_str = second_part.trim();
        if let Some(amount_str) = amount_str.trim() {
            let amount = amount_str.parse::<i64>().unwrap();
            if amount < -1000000 || amount > 1000000 {
                return Value::Null;
            }
            amount *= sign;
            has_dot = true;
        }
    }

    if !has_dot {
        return Value::Null;
    }

    Value::Number(serde_json::Number::from(amount))
}
